];
const ua = UAS[Math.floor(Math.random() * UAS.length)];
return [{ json: { userAgent: ua } }];

// ── OLX: Parse + Filter + Deduplicate ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentIds) staticData.sentIds = {};

const now = Date.now();
for (const id in staticData.sentIds) {
  if (now - staticData.sentIds[id] > 86400000) delete staticData.sentIds[id];
}

const raw = $input.first().json;
// OLX API: top-level ads array, atau nested
const ads = raw.data?.ads || raw.ads || raw.data || [];
if (!Array.isArray(ads)) {
  console.log('OLX: unexpected shape', JSON.stringify(raw).slice(0, 200));
  return [];
}

const output = [];

for (const ad of ads) {
  // ── Price ──
  const priceRaw = ad.price?.value?.raw || ad.price?.raw ||
    ad.priceValue || ad.price_value || 0;
  const price = parseInt(String(priceRaw).replace(/\D/g, ''));
  if (!price || price < 300000 || price > 800000) continue;

  // ── Location: must include Surabaya ──
  const locText = [
    ad.location?.city?.name, ad.location?.area?.name,
    ad.location?.subArea?.name, ad.title, ad.subject
  ].filter(Boolean).join(' ').toLowerCase();
  if (!locText.includes('surabaya') && !locText.includes('sby') &&
      !locText.includes('jawa timur')) continue;

  // ── Images ──
  const rawImgs = ad.images || ad.photos || [];
  const images = rawImgs
    .map(img => {
      if (typeof img === 'string') return img;
      // OLX stores multiple resolutions
      return img?.link || img?.url ||
        img?.resolutions?.find(r => r.width >= 400)?.link ||
        img?.resolutions?.[0]?.link || '';
    })
    .filter(u => u && u.startsWith('http'))
    .slice(0, 5);
  if (images.length === 0) continue;

  // ── Dedup ──
  const uid = 'olx_' + (ad.id || ad.listingId || ad.slug || '');
  if (!uid.replace('olx_', '') || staticData.sentIds[uid]) continue;
  staticData.sentIds[uid] = now;

  // ── URL ──
  const url = ad.url || ad.link || `https://www.olx.co.id/${ad.id}`;

  output.push({
    json: {
      source: 'olx',
      title: ad.title || ad.subject || 'Kos Surabaya',
      price,
      location: [
        ad.location?.subArea?.name,
        ad.location?.area?.name,
        ad.location?.city?.name
      ].filter(Boolean).join(', ') || 'Surabaya',
      url: url.startsWith('http') ? url : 'https://www.olx.co.id' + url,
      description: (ad.description || ad.shortDescription || '').slice(0, 500),
      images,
      scraped_at: new Date().toISOString()
    }
  });
}

console.log(`OLX: ${output.length} listings passed filters`);
return output;

